      "footnotesUr": "[1] ان صفات مذکورہ کے حامل مومن ہی فلاح یاب ہونگے جو جنت کے وارث یعنی حق دار ہوں گے۔ جنت بھی جنت الفردوس، جو جنت کا اعلٰی حصہ ہے۔ جہاں سے جنت کی نہریں جاری ہوتی ہیں (صحیح بخاری، کتاب الجہاد، باب درجات المجاہدین، فی سبیل اللہ، وکتاب التوحید، باب وکان عرشہ علی ماء)",
