      "arFull": "وَجَعَلْنَا ابْنَ مَرْیَمَ وَاُمَّهٗۤ اٰیَةً وَّاٰوَیْنٰهُمَاۤ اِلٰی رَبْوَةٍ ذَاتِ قَرَارٍ وَّمَعِیْنٍ ۟۠",
