      "ur": "اکڑتے اینٹھتے[1] افسانہ گوئی کرتے اسے چھوڑ دیتے تھے.[2]",
      "en": "In arrogance regarding it,[964] conversing by night, speaking evil.",
      "footnotesUr": "[1] به کا مرجع جمہور مفسرین نے ”البیت العتیق“ (خانہ کعبہ) یا حرم لیا ہے۔ یعنی انہیں اپنی تولیت خانہ کعبہ اور اس کا خادم و نگران ہونے کا جو غرور تھا، اس کی بنا پر آیات الٰہی کا انکار کیا اور بعض نے اس کا مرجع قرآن کو بنایا ہے اور مطلب یہ ہے کہ قرآن سن کر ان کے دل میں کھلبلی پیدا ہو جاتی جو انہیں قرآن پر ایمان لانے سے روک دیتی۔\n[2] سَمَر کے معنی ہیں رات کی گفتگو یہاں اس کے معنی خاص طور پر ان باتوں کے ہیں جو قرآن کریم اور نبی (صلى الله عليه وسلم) کے بارے میں وہ کرتے تھے اور اس کی بنا پر وہ حق کی بات سننے اور قبول کرنے سے انکار کر دیتے۔ یعنی چھوڑ دیتے۔ اور بعض نے ہجر کے معنی فحش گوئی کے کئے ہیں۔ یعنی راتوں کی گفتگو میں تم قرآن کی شان میں بےہودہ اور فحش باتیں کرتے ہو، جن میں کوئی بھلائی نہیں (فتح القدیر)",
      "footnotesEn": "[964] The revelation. Or \"him,\" i.e., the Prophet (ﷺ).",
