      "en": "My Lord, then do not place me among the wrongdoing people.\"",
      "footnotesUr": "[1] چنانچہ حدیث میں آتا ہے کہ نبی (صلى الله عليه وسلم) دعا فرماتے تھے «وإِذَا أَرَدْتَ بِقَوْمٍ فِتْنَةً فَتَوَفَّنِي إِلَيكَ غَيْرَ مَفْتُونٍ»، (ترمذی تفسیر سورۃ ص و مسند احمد، جلد 5، ص 243)۔ ”اے اللہ جب تو کسی قوم پر آزمائش یا عذاب بھیجنے کا فیصلہ کرے تو اس سے پہلے پہلے مجھے دنیا سے اٹھا لے“۔",
