      "footnotesUr": "[1] چہرے کا ذکر اس لئے کیا ہے کہ یہ انسانی وجود کا سب سے اہم اور اشرف حصہ ہے، ورنہ جہنم تو پورے جسم کو ہی محیط ہوگی۔\n[2] کَلَحً کے معنی ہوتے ہیں ہونٹ سکڑ کر دانت ظاہر ہو جائیں۔ ہونٹ گویا دانتوں کا لباس ہیں، جب یہ جہنم کی آگ سے سمٹ اور سکڑ جائیں گے تو دانت ظاہر ہو جائیں گے، جس سے انسان کی صورت بدشکل اور ڈراؤنی ہو جائے گی۔",
      "footnotesEn": "[968] Their lips having been contracted by scorching until the teeth are exposed.",
