      "en": "They will say, \"We remained a day or part of a day; ask those who enumerate.\"",
      "footnotesUr": "[1] اس سے مراد فرشتے ہیں، جو انسانوں کے اعمال اور عمریں لکھنے پر مامور ہیں یا وہ انسان مراد ہیں جو حساب کتاب میں مہارت رکھتے ہیں۔ قیامت کی ہولناکیاں، ان کے ذہنوں سے دنیا کی عیش و عشرت کو محو کر دیں گی اور دنیا کی زندگی انہیں ایسے لگے گی جیسے دن یا آدھا دن۔ اس لئے وہ کہیں گے کہ ہم تو ایک دن یا اس سے بھی کم وقت دنیا میں رہے۔ بیشک تو فرشتوں سے یا حساب جاننے والوں سے پوچھ لے۔",
