      "number": 117,
      "arFull": "وَمَنْ یَّدْعُ مَعَ اللّٰهِ اِلٰهًا اٰخَرَ ۙ لَا بُرْهَانَ لَهٗ بِهٖ ۙ فَاِنَّمَا حِسَابُهٗ عِنْدَ رَبِّهٖ ؕ اِنَّهٗ لَا یُفْلِحُ الْكٰفِرُوْنَ ۟",
      "ur": "جو شخص اللہ کے ساتھ کسی دوسرے معبود کو پکارے جس کی کوئی دلیل اس کے پاس نہیں، پس اس کا حساب تو اس کے رب کے اوپر ہی ہے۔ بےشک کافر لوگ نجات سے محروم ہیں.[1]",
      "en": "And whoever invokes besides Allāh another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.",
      "footnotesUr": "[1] اس سے معلوم ہوا کہ فلاح اور کامیابی آخرت میں عذاب الٰہی سے بچ جانا ہے، محض دنیا کی دولت اور آسائشوں کی فروانی، کامیابی نہیں، یہ دنیا میں کافروں کو بھی حاصل ہے، لیکن اللہ تعالٰی ان سے فلاح کی نفی فرما رہا ہے، جس کے صاف معنی یہ ہیں کہ اصل فلاح آخرت سے فلاح ہے جو اہل ایمان کے حصے آئے گی، نہ کہ دنیاوی مال و اسباب کی کثرت، جو کہ بلا تفریق مومن اور کافر، سب کو ہی حاصل ہوتی ہے۔",
